export class FrameQueue<T> {
    private slots: Array<T | undefined>;
    private head = 0;
    private count = 0;

    constructor(private capacity: number) {
        this.slots = new Array<T | undefined>(capacity);
    }

    enqueue(value: T): void {
        // TODO: write at the tail index and grow the count, wrapping with modulo
        this.slots.push(value);
        this.count += 1;
    }

    dequeue(): T | undefined {
        const value = this.slots.shift();
        this.count -= 1;
        return value;
    }

    get size(): number {
        return this.count;
    }
}
